package net.officefloor.hq.app.statement;

import net.officefloor.hq.app.history.SheetHistory;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/** Statements taken of people on a sheet. The caller's signed-in name comes in the {@code X-User} header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class StatementController {

    /** A person's statements: how many, and the last one's due-total ("n/a" when none could be given) and date. */
    public record SummaryView(long personId, int count, String dueTotal, LocalDate date) {

        public static SummaryView of(StatementService.Summary summary) {
            return new SummaryView(summary.personId(), summary.count(), summary.dueTotal(), summary.takenOn());
        }
    }

    /** A statement just taken: the person's summary and their claims as it left them, newest first. */
    public record TakenView(SummaryView summary, List<ClaimView> claims) {
    }

    private final StatementService statements;
    private final SheetHistory history;

    public StatementController(StatementService statements, SheetHistory history) {
        this.history = history;
        this.statements = statements;
    }

    @GetMapping("/statements")
    public List<SummaryView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(value = SheetHistory.AS_OF_HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        if (asOf != null) {
            return history.viewsAsOf(sheetId, asOf).statements();
        }
        return statements.list(sheetId).stream().map(SummaryView::of).toList();
    }

    @PostMapping("/people/{personId}/statements")
    public TakenView take(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long personId,
            @RequestParam(required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        StatementService.Taken taken = statements.take(sheetId, user, personId, asOf);
        return new TakenView(SummaryView.of(taken.summary()), taken.claims().stream().map(ClaimView::of).toList());
    }

    @DeleteMapping("/people/{personId}/statements/last")
    public TakenView cancel(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        StatementService.Taken cancelled = statements.cancel(sheetId, user, personId);
        return new TakenView(SummaryView.of(cancelled.summary()), cancelled.claims().stream().map(ClaimView::of).toList());
    }
}
package net.officefloor.hq.app.statement;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** A statement taken of a person: their due-total at that moment and the sheet's today then. */
@Entity
@Table(name = "statement")
public class Statement {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    /** The due-total with exactly two decimals, or "n/a" when the person's grade had no rate then. */
    @Column(name = "due_total", nullable = false)
    private String dueTotal;

    @Column(name = "taken_on", nullable = false)
    private LocalDate takenOn;

    protected Statement() {
    }

    public Statement(String sheetId, Long personId, String dueTotal, LocalDate takenOn) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.dueTotal = dueTotal;
        this.takenOn = takenOn;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public String getDueTotal() {
        return dueTotal;
